CREATE TABLE IF NOT EXISTS city_offers (id TEXT PRIMARY KEY, city_slug TEXT NOT NULL, section TEXT NOT NULL, source_version TEXT NOT NULL, data TEXT NOT NULL, extracted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS city_offers_city ON city_offers(city_slug,section);
CREATE TABLE IF NOT EXISTS research_coverage (city_slug TEXT NOT NULL, section TEXT NOT NULL, offers INTEGER NOT NULL DEFAULT 0, comparable INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(city_slug,section));
CREATE TABLE IF NOT EXISTS comparisons (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), slot TEXT NOT NULL, name TEXT NOT NULL, data TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,slot));
